import {fresh,restore,canEnter,ready,complete,experimentIssue,recordBank,progress,STORAGE_KEY,LEGACY_KEY,phaseReady as inquiryPhaseReady,remaining} from './inquiry-core.js';
import {createInquiryUI} from './inquiry-ui.js';
import {ART,SCENES,art,esc,BIO,CHAPTER_NAMES,REWARDS} from './adventure-assets.js';
import {mapMarkup,mountMap} from './adventure-map.js';
import {exportStorybook} from './adventure-export.js';

const app=document.querySelector('#app'),modal=document.querySelector('#modal'),toastNode=document.querySelector('#toast');
let state,storageHealthy=true,dispose=()=>{},selectedTool='',activeAnimal='butterfly',activePlant='balsam',animalStep=0,plantStep=0,toastTimer,returnFocus,lastRenderKey='',comparisonZoom=false;
try{state=restore(localStorage.getItem(STORAGE_KEY)||localStorage.getItem(LEGACY_KEY)||'null');}catch{state=fresh();storageHealthy=false;}
const iq=createInquiryUI({state:()=>state,save,render,toast,dialog,updateFooter});
const MISSIONS=[
 {title:'잎사귀 속 작은 생명',steps:['돋보기로 찾기','그림과 글로 남기기'],guide:['돋보기를 네 생물 위로 옮겨 봐. 무엇이 보이는지 자세히 살펴보자.','내 눈으로 본 모양을 그려 봐. 그림 옆에는 특징을 한 문장으로 적어 줘.'],goal:'흩어진 나비의 관찰 기록을 되찾자.',gain:'네 장의 관찰 사진이 다음 탐험의 단서가 돼.'},
 {title:'끊어진 한살이 필름',steps:['시간 순서 잇기','변화 찾아 설명하기'],guide:['관찰 사진을 옮겨 나비가 자라는 순서로 놓아 줘.','손잡이를 움직여 두 모습을 비교해 봐. 어른벌레가 낳은 알에서는 다음 세대가 시작돼.'],goal:'잎새가 뒤섞은 한살이 필름을 이어 줘.',gain:'시간 돋보기와 첫 번째 시계 고리를 얻어.'},
 {title:'두 씨앗의 공정한 출발',steps:['같은 화분 준비','한 가지 조건 바꾸기'],guide:['두 화분에 같은 흙과 같은 씨앗을 넣자. 씨앗 수는 각각 세 개야.','알아볼 조건 하나만 다르게 해 줘. 다른 조건은 씨앗이 싹 틀 수 있게 맞춰야 해.'],goal:'씨앗이 싹 트는 데 필요한 조건을 알아보자.',gain:'내가 설계한 실험이 다음 활동에서 그대로 자라.'},
 {title:'흙 속에서 일어난 일',steps:['시간을 움직여 관찰','사진으로 설명하기'],guide:['시간 손잡이를 움직여 봐. 처음·중간·마지막 사진을 남기고 시간 돋보기로 뿌리도 살펴봐.','직접 모은 사진을 보고 어느 쪽이 싹 텄는지, 어떤 조건 때문인지 설명해 줘.'],goal:'씨앗이 바뀌는 순간을 놓치지 말자.',gain:'비교 렌즈와 두 번째 시계 고리를 얻어.'},
 {title:'온실 탐정의 실험',steps:['센서로 살펴보기','다르게 놓고 예상하기'],guide:['물 센서와 빛 센서를 두 화분에 하나씩 놓아 봐. 보이지 않는 조건을 읽을 수 있어.','이번에는 자라는 식물을 비교해. 물 또는 햇빛 중 알아볼 조건 하나만 다르게 하자.'],goal:'온실의 식물이 잘 자라는 조건을 찾아 줘.',gain:'내 조건에 따라 다음 온실의 식물 모습이 달라져.'},
 {title:'식물이 보낸 구조 신호',steps:['근거를 찾아 진단','필요한 조건 돌려주기'],guide:['잎과 줄기를 자세히 봐. 식물이 잘 자라는지는 키 하나로 정할 수 없어.','찾은 원인에 맞는 도구를 식물에 가져가 줘. 좋아진 모습을 보며 내 생각을 기록하자.'],goal:'약해진 식물에게 필요한 도움을 찾아 줘.',gain:'계절 렌즈와 세 번째 시계 고리를 얻어.'},
 {title:'같고도 다른 생명의 시간',steps:['동물의 시작 비교','일 년 뒤 정원 비교'],guide:['나비와 개의 시간을 끝까지 살펴봐. 태어나는 모습은 어떻게 다를까?','계절 렌즈를 돌려 일 년을 지나 보자. 같은 식물이 살아 있는지, 씨앗에서 새 식물이 시작하는지 봐.'],goal:'모든 생물이 같은 한살이를 보내는지 찾아보자.',gain:'동물과 식물의 비교 사진이 이야기 책에 남아.'},
 {title:'생명 정원의 새 이웃',steps:['알맞은 정원으로 안내','새로운 식물에 적용'],guide:['생물 카드를 알맞은 정원으로 데려다 줘. 동물은 태어나는 방법, 식물은 살아가는 해를 기준으로 나눠.','처음 만나는 장미 이야기에도 배운 기준을 써 보자.'],goal:'생물마다 알맞은 정원 표지판을 찾아 줘.',gain:'이야기 카메라와 네 번째 시계 고리를 얻어.'},
 {title:'내가 만든 한살이 이야기',steps:['관찰 기록 고르기','설명 쓰고 공유하기'],guide:['직접 모은 사진을 책에 세 장 이상 놓아 줘. 동물과 식물 이야기를 모두 담자.','사진 두 장 이상에 내 설명을 적고, 동물과 식물의 한살이를 비교한 생각을 끝에 남겨 줘.'],goal:'다른 친구에게 들려줄 나만의 한살이 책을 만들자.',gain:'완성한 책을 그림 파일로 저장하거나 화면으로 발표할 수 있어.'},
 {title:'다시 움직이는 생명 시계',steps:['내 기록으로 시계 복원','교실 밖 탐험 약속'],guide:['네 구역에서 모은 고리를 제자리에 끼워 줘. 마지막 고리는 완성한 이야기 책의 힘으로 빛나.','모의 관찰에서 찾은 것을 주변 생물에게도 적용해 보자. 무엇을 어떻게 관찰할지 정해 줘.'],goal:'탐험에서 모은 증거로 생명 시계를 다시 움직이자.',gain:'생명 탐험가가 되고 내 이야기를 다시 펼칠 수 있어.'}
];
const btn=(label,action,value='',cls='',disabled=false)=>`<button class="${cls}" data-action="${action}" data-value="${esc(value)}" ${['question','prediction','winner','reason','trait','cause','birth','perennial'].includes(action)?`aria-pressed="${cls==='selected'}"`:''} ${action==='condition'?`aria-label="${String(value).split(':')[1].toUpperCase()} 화분 · ${label.replace(/<[^>]*>/g,'')}"`:''} ${disabled?'disabled':''}>${label}</button>`;
const field=(label,path,value,placeholder='',rows=2)=>`<label class="field"><span>${label}</span><textarea data-field="${path}" rows="${rows}" maxlength="${path==='book.summary'?350:180}" placeholder="${esc(placeholder)}">${esc(value)}</textarea></label>`;
const tool=(id,key,label)=>`<button class="tool ${selectedTool===id?'selected':''}" data-carry="${id}" aria-pressed="${selectedTool===id}" aria-label="${label} 도구 선택">${art(key)}<span>${label}</span></button>`;
function save(){const wasHealthy=storageHealthy;try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageHealthy=true;}catch{storageHealthy=false;if(wasHealthy)toast('기기에 저장하지 못했어. 창을 닫기 전에 이야기 그림을 저장해 줘.');}const node=document.querySelector('#save-state');if(node){node.textContent=storageHealthy?'저장됨':'저장 안 됨';node.classList.toggle('save-error',!storageHealthy);}}
function toast(message){clearTimeout(toastTimer);toastNode.textContent=message;toastNode.classList.add('visible');toastTimer=setTimeout(()=>toastNode.classList.remove('visible'),4200);}
function dialog(content){returnFocus=document.activeElement;modal.innerHTML=content;const heading=modal.querySelector('h2');if(heading){heading.id='dialog-heading';modal.setAttribute('aria-labelledby','dialog-heading');}modal.showModal();modal.querySelector('button,textarea,input')?.focus();}
modal.addEventListener('close',()=>{iq.stop();if(state.intro){state.intro=false;save();}if(returnFocus?.isConnected)returnFocus.focus();});
function header(){const p=progress(state);return `<header class="topbar"><button class="brand" data-action="map" aria-label="생명 시계 연구실 지도">${art('core')}<span>생명 시계 연구실<small>LIFE CLOCK LAB</small></span></button><div class="journey-progress" aria-label="${p.completed}개 탐험 완료"><span>숲의 빛을 되찾는 여행</span><div class="progress-track"><i style="width:${p.percent}%"></i></div><strong>${p.completed} / 10</strong></div><div class="header-actions">${btn("내 기록","records","","icon-button")}<span id="save-state" class="${storageHealthy?'':'save-error'}">${storageHealthy?'저장됨':'저장 안 됨'}</span>${btn('도움말','help','','icon-button')}</div></header>`;}
function render({focus=false}={}){iq.stop();dispose();dispose=()=>{};const old=document.activeElement,focusField=old?.dataset?.field,selection=focusField?[old.selectionStart,old.selectionEnd]:null;const action=old?.dataset?.action,value=old?.dataset?.value,carry=old?.dataset?.carry,drop=old?.dataset?.drop;const key=state.screen+':'+state.mission+':'+state.phase[state.mission],scroll=key===lastRenderKey?app.querySelector('.activity')?.scrollTop||0:0;lastRenderKey=key;app.innerHTML=header()+(state.screen==='mission'?missionMarkup():mapScreen());if(state.screen==='mission')mountMission();else dispose=mountMap(app,state,{save,enter:enterChapter,notify:toast});bindDrawing();iq.bind();const activity=app.querySelector('.activity');if(activity)activity.scrollTop=scroll;
 if(focus){const heading=app.querySelector('h1');heading?.setAttribute('tabindex','-1');heading?.focus();}else if(focusField){const same=app.querySelector(`[data-field="${focusField}"]`);same?.focus();if(selection)same?.setSelectionRange(...selection);}else if(action){[...app.querySelectorAll('[data-action]')].find(n=>n.dataset.action===action&&n.dataset.value===value&&!n.disabled)?.focus();}else if(carry||drop){const same=[...app.querySelectorAll('[data-carry],[data-drop]')].find(n=>carry?n.dataset.carry===carry:n.dataset.drop===drop);same?.focus();}
 if(state.intro&&state.screen!=='mission')showIntro();}
function mapScreen(){const count=state.completed.length;return `<main class="map-screen"><div class="map-heading"><div><p class="eyebrow">지훈 & 잎새의 생명 탐험</p><h1>${count===10?'숲에 생명의 시간이 돌아왔어!':'멈춘 생명 시계에 빛을 돌려줘'}</h1></div><div class="map-rewards">${REWARDS.map((r,i)=>`<span class="reward-token ${state.completed.includes(i*2+1)?'earned':''}" title="${r.name}">${art(r.art,r.name)}</span>`).join('')}</div></div>${mapMarkup(state)}<div class="quick-missions">${MISSIONS.filter((_,n)=>canEnter(state,n)).map((m,n)=>btn(`${n+1}. ${m.title}`,"open-mission",n,n===state.completed.length?"primary":"")).join("")}</div><div class="map-footnote"><span>장소 선택 · 길을 따라 이동 · 도착하면 탐험 시작</span>${btn('모은 기록 보기','records')}${btn('선생님 안내','teacher')}</div></main>`;}
function showIntro(){dialog(`<div class="intro-dialog">${art('jihoon','','intro-person')}<div><p class="eyebrow">오늘부터 우리는 생명 탐험가!</p><h2>숲의 시계가 멈췄어.</h2><p>나비가 변하는 모습도, 씨앗이 자라는 시간도 뒤섞여 버렸어.</p><p><strong>살펴보고, 실험하고, 증거를 모아</strong><br>잎새와 함께 다섯 구역의 빛을 찾아 줘.</p><div class="intro-route">관찰 → 실험 → 비교 → 나만의 이야기</div>${btn('잎새와 숲길로 출발!','start','','primary')}</div></div>`);}
function openMission(n){if(!canEnter(state,n))return toast('앞 탐험의 기록이 먼저 필요해.');state.mission=n;state.screen='mission';selectedTool='';save();render({focus:true});}
function enterChapter(chapter){const first=chapter*2;if(state.completed.includes(first)){dialog(`<div class="help-dialog"><p class="eyebrow">${CHAPTER_NAMES[chapter]}</p><h2>어떤 기록을 이어 볼까?</h2><p>완료한 탐험의 관찰과 이야기도 다시 펼칠 수 있어.</p><div class="chapter-options">${[first,first+1].map(n=>btn(`${state.completed.includes(n)?'✓ 기록 다시 보기':'다음 탐험'} · ${MISSIONS[n].title}`,'open-mission',n,n===first+1?'primary':'')).join('')}</div>${btn('닫기','close')}</div>`);return;}openMission(first);}
function missionMarkup(){const n=state.mission,m=MISSIONS[n],p=state.phase[n]||0;return `<main class="mission-screen" data-mission="${n}" data-phase="${p}" style="--scene:url('${SCENES[n]}')"><div class="mission-heading"><div><p class="eyebrow">${CHAPTER_NAMES[Math.floor(n/2)]} · 탐험 ${String(n+1).padStart(2,'0')}</p><h1>${m.title}</h1></div><ol class="stepper">${m.steps.map((x,i)=>`<li class="${i===p?'current':i<p?'done':''}"><span>${i<p?'✓':i+1}</span>${x}</li>`).join('')}</ol></div><div class="mission-layout"><section class="activity" aria-label="탐험 활동">${iq.view(n,p)??activities[n](p)}</section></div><footer class="mission-footer"><div>${btn(p?'앞 활동':'숲 지도',p?'phase-back':'map','','subtle')}<span class="footer-status" id="phase-status">${phaseStatus()}</span></div>${btn(p===0?'다음 활동으로':state.completed.includes(n)?'완료한 탐험 · 지도 보기':'탐험 마치기',p===0?'phase-next':'finish','','primary',p===0?!phaseReady():!ready(state,n))}</footer></main>`;}
function phaseStatus(){return remaining(state,state.mission,state.phase[state.mission]);}
function phaseReady(){return inquiryPhaseReady(state);}
function updateFooter(){const p=state.phase[state.mission];const next=app.querySelector('[data-action="'+(p?'finish':'phase-next')+'"]');if(next)next.disabled=p?!ready(state,state.mission):!phaseReady();const status=app.querySelector('#phase-status');if(status)status.textContent=phaseStatus();}

function observation(p){if(!p)return `<div class="leaf-world" style="background-image:url('${ART.leaf}')"><div class="scene-caption"><strong>작은 생명의 흔적을 찾아라</strong><span>돋보기를 생물에 끌어 놓아 봐 · 도구 선택 후 생물을 눌러도 돼</span></div>${BIO.map((b,i)=>`<button class="specimen hotspot ${state.discovery.seen.includes(b.id)?'found':''}" style="--x:${[21,46,72,55][i]}%;--y:${[38,55,35,24][i]}%" data-drop="inspect:${b.id}" aria-label="${b.name} 관찰하기">${art(b.id)}<span>${state.discovery.seen.includes(b.id)?'✓ '+b.name:'관찰 지점 '+(i+1)}</span></button>`).join('')}<div class="scene-counter">관찰한 생물 <strong>${state.discovery.seen.length} / 4</strong></div></div><div class="tooltray">${tool('magnifier','magnifier','돋보기')}<p>도구를 집어 생물 위에 놓아 줘.<small>마우스 · 터치 · 도구 선택 후 대상 선택</small></p></div>`;
 return `<div class="activity-intro"><h2>관찰한 모습을 내 기록으로</h2><p>모형에서 본 특징 한 가지를 그림과 글로 표현해 봐.</p></div><div class="draw-layout"><div class="drawing-paper"><div class="drawing-reference">${BIO.map(b=>art(b.id,b.name)).join('')}</div><canvas id="observation-drawing" width="720" height="420" tabindex="0" aria-label="관찰 그림 그리기. 마우스나 손가락으로 그리세요. 키보드는 스페이스로 펜을 내리고 방향키로 그릴 수 있어요."></canvas><div class="drawing-tools"><span>✎ 관찰 연필</span>${btn('그림 지우기','clear-drawing')}</div></div><div class="writing-area">${field('내가 발견한 특징','discovery.note',state.discovery.note,'예: 애벌레의 몸은 … 모양이고 …이 보여.')}<p class="hint">그림은 잘 그리는 것보다 관찰한 특징을 담는 게 중요해.</p><p class="hint">키보드로 그리기: 스페이스 → 방향키 → 스페이스</p></div></div>`;}
function cycle(p){if(!p)return `<div class="activity-intro"><h2>네 장의 사진을 시간 순서대로</h2><p>사진을 원하는 자리로 옮겨. 사진 선택 후 다른 자리를 눌러도 바꿀 수 있어.</p></div><div class="filmline">${state.cycle.order.map((id,i)=>`<button class="film-card" data-carry="cycle:${i}" data-drop="cycle:${i}" aria-label="${i+1}번 ${BIO.find(x=>x.id===id).name}, 사진 옮기기"><span class="frame-number">${i+1}</span>${art(id)}<strong>${BIO.find(x=>x.id===id).name}</strong></button>`).join('')}</div><div class="gentle-feedback">${phaseReady()?'✓ 알 → 애벌레 → 번데기 → 어른벌레로 이어졌어.':'먼저 알에서 시작해. 모습이 어떻게 달라졌는지 떠올려 봐.'}</div>`;
 return `<div class="compare-layout"><div><div class="wipe-view"><div>${art('larva','애벌레')}<strong>애벌레</strong></div><div class="wipe-after" style="clip-path:inset(0 0 0 50%)">${art('adult','어른벌레')}<strong>어른벌레</strong></div><span class="wipe-handle" style="left:50%">↔</span></div><label class="slider-label">비교 손잡이를 움직여 봐<input type="range" min="0" max="100" value="50" data-range="compare" aria-label="애벌레와 어른벌레 비교 손잡이"></label></div><div class="writing-area">${field('무엇이 달라졌을까?','cycle.note',state.cycle.note,'몸의 모양, 다리, 날개를 비교해 봐.')}<div class="generation"><span>어른벌레가 낳은 알</span><button class="next-egg" data-carry="new-egg" aria-label="다음 세대의 알 집기">${art('egg')}</button><button class="generation-slot ${state.cycle.generation?'filled':''}" data-drop="generation">${state.cycle.generation?'✓ 다음 세대가 시작돼':'여기에 다음 세대의 알 놓기'}</button></div></div></div>`;}
function questionChoice(kind){const e=state[kind],isSeed=kind==='seed',locked=state.completed.includes(isSeed?2:4);return `<div class="question-picker"><strong>알아보고 싶은 조건</strong>${(isSeed?[['water','물'],['warm','온도']]:[['light','햇빛'],['water','물']]).map(([value,label])=>btn(label,'question',kind+':'+value,e.question===value?'selected':'',locked)).join('')}</div>`;}
function prepPot(k){const e=state.seed.prepared[k];return `<button class="prep-pot" data-drop="prepare:${k}" aria-label="화분 ${k.toUpperCase()} 준비"><span class="pot-badge">${k.toUpperCase()}</span>${art(e.seeds?'pot0':e.soil?'soil':'vessel')}<strong>${e.seeds?'같은 씨앗 3개':e.soil?'같은 양의 흙':'비어 있는 화분'}</strong><span>${e.soil?'✓ 흙':'흙을 넣어 줘'} · ${e.seeds?'✓ 씨앗':'씨앗을 넣어 줘'}</span></button>`;}
function seedLab(p){if(!p)return `<div class="activity-intro"><h2>출발은 똑같이 준비해</h2><p>흙 도구와 씨앗 도구를 두 화분에 각각 놓아 줘.</p></div><div class="pots prepare-pots">${prepPot('a')}${prepPot('b')}</div><div class="tooltray">${tool('soil','soil','같은 양의 흙')}${tool('seeds','seed0','씨앗 3개')}<p>두 화분에 같은 종류의 씨앗을 세 개씩.<small>한 번 놓으면 같은 양이 담겨.</small></p></div>`;
return `${questionChoice('seed')}<div class="pots conditions">${conditionPot('seed','a')}${conditionPot('seed','b')}</div>${experimentFeedback('seed')}${prediction('seed')}`;}
function conditionPot(kind,k){const e=state[kind][k],seed=kind==='seed',locked=state.completed.includes(seed?2:4);return `<div class="condition-pot"><span class="pot-badge">${k.toUpperCase()}</span>${art(seed?'pot0':'pot3')}<div class="condition-buttons">${btn(`${art('watercan')}<span>물 ${e.water?'있음':'없음'}</span>`,'condition',`${kind}:${k}:water`,e.water?'on':'off',locked)}${btn(`${art(seed?'lamp':e.light?'lamp':'shade')}<span>${seed?'온도 '+(e.warm?'따뜻함':'차가움'):'빛 '+(e.light?'밝음':'어두움')}</span>`,'condition',`${kind}:${k}:${seed?'warm':'light'}`,e[seed?'warm':'light']?'on':'off',locked)}</div></div>`;}
function experimentFeedback(kind){const issue=experimentIssue(state[kind],state[kind].question);return `<div class="gentle-feedback ${issue?'':'success'}">${issue==='difference'?'알아볼 조건만 서로 다르게! 다른 조건은 같아야 비교할 수 있어.':issue==='baseline'?'같게 둔 조건도 확인해 줘. 두 식물 모두 자랄 수 있는 출발이어야 해.':'✓ 알아볼 조건 하나만 달라. 공정하게 비교할 수 있어.'}${state.completed.includes(kind==='seed'?2:4)?'<small>진행한 실험 조건은 관찰 기록과 함께 보관돼.</small>':''}</div>`;}
function prediction(kind){return `<div class="prediction"><strong>어느 화분에서 더 잘 ${kind==='seed'?'싹 틀':'자랄'}까?</strong><span>예상은 달라도 괜찮아. 관찰로 확인하자.</span>${[['a','A'],['b','B'],['both','둘 다'],['neither','둘 다 아님'],['unsure','아직 모르겠어']].map(([k,t])=>btn(t,'prediction',kind+':'+k,state[kind].prediction===k?'selected':'')).join('')}</div>`;}
const seedLevel=(k,day)=>state.seed[k].water&&state.seed[k].warm?(day<2?0:day<4?1:day<6?2:3):0;
function growingPots(){return `<div class="pots growing">${['a','b'].map(k=>`<div class="growth-pot"><span class="pot-badge">${k.toUpperCase()}</span>${art('pot'+seedLevel(k,state.journey.day))}<span class="soil-cover ${state.journey.peek?'peeked':''}">${state.journey.peek?'✓ 흙 속도 관찰했어':'흙 속을 보여 주는 단면 모형'}</span><strong>${seedLevel(k,state.journey.day)?['씨앗','뿌리가 나와','싹이 올라와','잎이 펼쳐져'][seedLevel(k,state.journey.day)]:'아직 싹이 보이지 않아'}</strong></div>`).join('')}</div>`;}
function journey(p){if(!p)return `<div class="activity-intro"><h2>시간을 움직이면 보이는 변화</h2><p>모의 관찰이야. 실제 자라는 속도는 생물과 환경에 따라 달라.</p></div>${growingPots()}<div class="time-table">${art('lever','','time-lever')}<label><strong id="day-label">${state.journey.day}일째</strong><input type="range" min="0" max="7" step="1" value="${state.journey.day}" data-range="day" aria-label="씨앗 관찰 날짜"><span>0일 · 처음<span>7일 · 마지막</span></span></label>${btn('흙 속 들여다보기','peek','','tool-action')}${btn('지금 모습 촬영','snapshot','','primary')}</div><div class="photo-checks">${[['처음',x=>x===0],['중간',x=>x>=2&&x<=4],['마지막',x=>x>=6&&x<=7]].map(([name,test])=>`<span class="${state.journey.shots.some(x=>test(x.day))?'done':''}">${state.journey.shots.some(x=>test(x.day))?'✓':'○'} ${name} 사진</span>`).join('')}</div>`;
return `<div class="activity-intro"><h2>내 사진이 말해 주는 것</h2><p>내 예상은 <strong>${state.seed.prediction?.toUpperCase()} 화분</strong>이었어. 사진에 보이는 증거로 생각을 확인해.</p></div><div class="evidence-strip">${[...state.journey.shots].sort((a,b)=>a.day-b.day).map(x=>`<div class="evidence-photo"><strong>${x.day}일째</strong><div>${art('pot'+seedLevel('a',x.day))}${art('pot'+seedLevel('b',x.day))}</div><span>A &nbsp;&nbsp; B</span></div>`).join('')}</div><div class="answer-row"><strong>싹이 튼 화분은</strong>${['a','b'].map(k=>btn(k.toUpperCase()+' 화분','winner',k,state.journey.winner===k?'selected':'')).join('')}<strong>어떤 조건 때문일까?</strong>${[['water','물'],['warm','알맞은 온도']].map(([k,t])=>btn(t,'reason',k,state.journey.reason===k?'selected':'')).join('')}</div>`;}
function greenhouse(p){if(!p)return `<div class="activity-intro"><h2>물과 빛을 읽는 온실 탐정</h2><p>물 센서는 흙의 물기를, 빛 센서는 밝기를 알려 줘.</p></div><div class="pots sensor-pots">${['a','b'].map(k=>`<div class="sensor-pot"><span class="pot-badge">${k.toUpperCase()}</span>${art('pot3')}<div class="sensor-slots">${['water','light'].map(type=>`<button class="sensor-slot ${state.greenhouse.sensors.includes(k+'-'+type)?'filled':''}" data-drop="sensor:${k}-${type}" aria-label="${k.toUpperCase()} 화분 ${type==='water'?'물':'빛'} 센서 자리">${state.greenhouse.sensors.includes(k+'-'+type)?art(type==='water'?'moistureSensor':'lightSensor'):'＋'}<span>${state.greenhouse.sensors.includes(k+'-'+type)?(type==='water'?'흙: 촉촉해':'빛: 밝아'):(type==='water'?'물 센서 놓기':'빛 센서 놓기')}</span></button>`).join('')}</div></div>`).join('')}</div><div class="tooltray">${tool('sensor-water','moistureSensor','물 센서')}${tool('sensor-light','lightSensor','빛 센서')}<p>센서를 알맞은 자리에 놓아 봐.<small>두 화분의 출발 조건을 확인하자.</small></p></div>`;
return `${questionChoice('greenhouse')}${iq.sensorReadings()}<div class="pots conditions">${conditionPot('greenhouse','a')}${conditionPot('greenhouse','b')}</div>${experimentFeedback('greenhouse')}${prediction('greenhouse')}`;}
const weakSide=()=>state.greenhouse.a[state.greenhouse.question]?'b':'a';
const correctTraits=()=>state.greenhouse.question==='light'?['color','stem']:['leaf','soil'];
function recovery(p){const weak=weakSide(),kind=state.greenhouse.question;return `<div class="activity-intro"><h2>${p?'필요한 조건을 되찾아 줘':'온실에서 며칠이 지난 뒤…'}</h2><p>${p?'알맞은 도구를 약해진 식물에게 놓아 봐.':'내 예상은 '+state.greenhouse.prediction?.toUpperCase()+' 화분이었어. 키뿐 아니라 잎과 줄기도 함께 살펴봐.'}</p></div><div class="pots diagnosis ${comparisonZoom?'zoomed':''}">${['a','b'].map(k=>`<button class="diagnosis-pot ${k===weak?'weak':''}" ${p?`data-drop="repair:${k}"`:''} aria-label="${k.toUpperCase()} 화분 관찰"><span class="pot-badge">${k.toUpperCase()}</span>${art(k===weak&&!state.recovery.repaired?kind==='light'?'pale':'dry':'pot3')}<strong>${k===weak&&!state.recovery.repaired?kind==='light'?'잎이 연하고 줄기가 가늘어':'잎이 처지고 흙이 말랐어':'잎이 푸르고 줄기가 튼튼해'}</strong></button>`).join('')}</div>${!p?`${btn(comparisonZoom?'비교 렌즈 접기':'얻은 비교 렌즈로 확대','compare-zoom','','lens-toggle')}<div class="trait-picks"><strong>약해진 모습의 근거 두 가지</strong>${[['color','연한 잎 색'],['stem','가늘고 긴 줄기'],['leaf','처진 잎'],['soil','마른 흙']].map(([k,t])=>btn(t,'trait',k,state.recovery.traits.includes(k)?'selected':'')).join('')}</div><div class="answer-row"><strong>부족한 조건은?</strong>${[['light','햇빛'],['water','물']].map(([k,t])=>btn(t,'cause',k,state.recovery.cause===k?'selected':'')).join('')}</div>`:`<div class="tooltray">${tool('repair-water','watercan','물 주기')}${tool('repair-light','lamp','밝은 곳으로')}<p>${state.recovery.repaired?'✓ 필요한 조건을 돌려줬어. 시간이 지나며 건강해졌어.':'약해진 '+weak.toUpperCase()+' 화분에 필요한 도구를 놓아 줘.'}<small>실제 식물은 조건을 바꾼 즉시 회복되지 않아.</small></p></div>${field('식물을 도운 방법과 근거','recovery.note',state.recovery.note,'무엇이 부족했는지, 어떤 모습으로 알았는지 적어 줘.')}`}`;}

const animalData={butterfly:{name:'나비',stages:[['알','egg','어른벌레가 낳은 알에서 시작해.'],['애벌레','larva','잎을 먹고 몸집이 커져.'],['번데기','pupa','껍질 안에서 몸의 모습이 바뀌어.'],['어른벌레','adult','날개가 있는 어른벌레가 다음 세대의 알을 낳아.']]},dog:{name:'개',stages:[['새끼','puppy','어미의 몸에서 새끼로 태어나.'],['자라는 개','dogYoung','먹이를 먹으며 몸집이 커져. 번데기 시기는 없어.'],['다 자란 개','dog','다 자라면 다음 세대의 새끼를 낳을 수 있어.']]}};
const plantData={balsam:{name:'봉선화',stages:[['봄 · 씨앗과 싹','balsamSprout','씨앗에서 새로운 식물이 시작해.'],['여름 · 자라고 꽃피기','balsam','잎과 줄기가 자라고 꽃이 피어.'],['가을 · 씨앗 맺기','balsamSeeds','꽃 뒤에 열매와 씨앗이 생겨.'],['겨울 · 한살이를 마침','balsamDry','원래 식물은 죽어. 남은 씨앗에서 다음 해 새 식물이 자라.']]},apple:{name:'사과나무',stages:[['봄 · 새잎이 나기','appleSpring','지난해부터 살아 있던 같은 나무에 새잎이 나.'],['여름 · 열매 자라기','appleSummer','꽃이 진 뒤 열매가 자라.'],['가을 · 열매 익기','apple','열매와 씨앗을 맺어. 씨앗을 맺어도 나무가 바로 죽지는 않아.'],['겨울 · 겨울나기','winter','잎은 떨어져도 같은 나무가 살아서 겨울을 나.']]}};
function archives(p){const type=p?'plant':'animal',data=p?plantData:animalData,id=p?activePlant:activeAnimal,step=p?plantStep:animalStep,entry=data[id],stage=entry.stages[step],seen=state.archives[p?'plantSeen':'animalSeen'];return `<div class="activity-intro"><h2>${p?'한 해가 지나면 누가 남을까?':'처음과 마지막을 이어 살펴봐'}</h2><p>${p?'계절 렌즈로 같은 식물의 시간을 따라가 봐.':'생물마다 단계 수와 이름이 달라. 같은 번호끼리 같은 시기라는 뜻은 아니야.'}</p></div><div class="archive-layout"><div class="species-rail">${Object.entries(data).map(([key,d])=>`<button data-action="archive-species" data-value="${type}:${key}" class="species-choice ${key===id?'selected':''}">${art(key==='butterfly'?'adult':key)}<strong>${d.name}</strong><span>${seen.includes(key+'-0')&&seen.includes(key+'-'+(d.stages.length-1))?'✓ 처음과 끝 관찰':'처음과 끝을 살펴봐'}</span></button>`).join('')}</div><div class="time-window"><div class="timeline-art">${art(stage[1],entry.name+' '+stage[0])}${p?art('season','','season-dial'):''}</div><h3>${entry.name} · ${stage[0]}</h3><p>${stage[2]}</p><label class="slider-label">${p?'계절 렌즈':'관찰 시간'}<input type="range" min="0" max="${entry.stages.length-1}" value="${step}" step="1" data-range="archive-${type}" aria-label="${entry.name} ${p?'계절':'한살이'} 시간"><span>${entry.stages[0][0]}<span>${entry.stages.at(-1)[0]}</span></span></label>${btn('이 모습 기록하기','archive-capture',type)}</div></div><div class="answer-row"><strong>${p?'겨울을 난 사과나무는?':'나비와 개가 태어나는 방법은?'}</strong>${(p?[['same','지난해의 같은 나무야'],['new','모두 새 씨앗에서 자랐어']]:[['different','알과 새끼로 서로 달라'],['same','둘 다 알에서 나와']]).map(([v,t])=>btn(t,p?'perennial':'birth',v,state.archives[p?'perennial':'birth']===v?'selected':'')).join('')}</div>`;}
const classification={butterfly:'egg',frog:'egg',chicken:'egg',dog:'live',balsam:'annual',apple:'perennial',rose:'perennial'};
const speciesNames={butterfly:'나비',frog:'개구리',chicken:'닭',dog:'개',balsam:'봉선화',apple:'사과나무',rose:'장미'};
const groupNames={egg:'알에서 태어나는 동물',live:'새끼로 태어나는 동물',annual:'한해살이 식물',perennial:'여러해살이 식물'};
function garden(p){const pool=(p?['rose']:Object.keys(classification).filter(x=>x!=='rose'));return `<div class="activity-intro"><h2>${p?'새 이웃 장미의 자리 찾기':'생물의 한살이 정원'}</h2><p>${p?'장미는 여러 해 동안 살아. 겨울을 난 같은 줄기에서 새잎과 꽃이 다시 나. 이 단서로 집을 찾아 줘.':'카드를 집어 알맞은 정원에 놓아 줘. 선택 후 정원을 눌러도 돼.'}</p></div><div class="garden-pool">${pool.filter(id=>!state.garden.placements[id]).map(id=>`<button class="species-card" data-carry="species:${id}" aria-label="${speciesNames[id]} 카드 집기">${id==='rose'?'<span class="rose-symbol" aria-hidden="true">🌹</span>':art(id)}<strong>${speciesNames[id]}</strong></button>`).join('')||'<p class="complete-message">✓ 모두 자기 정원을 찾았어!</p>'}</div><div class="garden-zones">${Object.entries(groupNames).filter(([id])=>!p||['annual','perennial'].includes(id)).map(([id,name])=>`<button class="garden-zone" data-drop="garden:${id}"><strong>${name}</strong><span>${id==='annual'?'한 해 동안 한살이를 마쳐':id==='perennial'?'여러 해를 이어 살아':id==='egg'?'어미가 낳은 알에서 시작':'어미의 몸에서 새끼로 시작'}</span><div>${Object.entries(state.garden.placements).filter(([,g])=>g===id).map(([s])=>`<span class="planted-species">${s==='rose'?'<span>🌹</span>':art(s)}${speciesNames[s]}</span>`).join('')}</div></button>`).join('')}</div>`;}
const recordThumbnails=new Map(),pendingThumbnails=new Map(),bitmapCache=new Map();
function bitmap(path){if(!bitmapCache.has(path))bitmapCache.set(path,new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>{bitmapCache.delete(path);reject(new Error('관찰 그림을 불러오지 못했어.'));};image.src=path;}));return bitmapCache.get(path);}
function thumbnailKey(r){return r.id==='drawing'?'drawing:'+JSON.stringify(state.discovery.drawing):r.id.startsWith('seed-')?r.id+':'+JSON.stringify([state.seed.a,state.seed.b]):r.id;}
function recordImage(r){const key=thumbnailKey(r);if(recordThumbnails.has(key))return recordThumbnails.get(key);if(r.evidence||r.id.startsWith('seed-')||r.id==='drawing')prepareThumbnail(r).catch(()=>{});return recordThumbnails.get(key)||ART[r.art]||ART.pot3;}
async function prepareThumbnail(r){const key=thumbnailKey(r);if(recordThumbnails.has(key))return recordThumbnails.get(key);if(pendingThumbnails.has(key))return pendingThumbnails.get(key);
 const task=(async()=>{if(r.evidence){const url=await iq.thumbnail(r);recordThumbnails.set(key,url);document.querySelectorAll('img[data-record-thumb]').forEach(img=>{if(img.dataset.recordThumb===r.id)img.src=url;});return url;}const canvas=document.createElement('canvas');canvas.width=720;canvas.height=480;const ctx=canvas.getContext('2d');ctx.fillStyle='#fffcf0';ctx.fillRect(0,0,720,480);
 if(r.id==='drawing'){ctx.strokeStyle='#315d45';ctx.lineWidth=4;ctx.lineCap='round';ctx.lineJoin='round';state.discovery.drawing.forEach(stroke=>{ctx.beginPath();stroke.forEach(([x,y],i)=>i?ctx.lineTo(x*680+20,y*400+20):ctx.moveTo(x*680+20,y*400+20));ctx.stroke();});ctx.fillStyle='#315d45';ctx.font='bold 24px "Malgun Gothic",sans-serif';ctx.textAlign='center';ctx.fillText('내가 관찰하고 그린 모습',360,460);}
 else{const day=+r.id.slice(5),images=await Promise.all(['a','b'].map(k=>bitmap(ART['pot'+seedLevel(k,day)])));ctx.textAlign='center';ctx.fillStyle='#315d45';ctx.font='bold 26px "Malgun Gothic",sans-serif';ctx.fillText(day+'일째 · 내가 설계한 씨앗 실험',360,38);images.forEach((image,i)=>{const scale=Math.min(325/image.width,335/image.height),w=image.width*scale,h=image.height*scale;ctx.drawImage(image,30+i*350+(320-w)/2,62+(335-h)/2,w,h);const k=i?'b':'a';ctx.font='bold 24px "Malgun Gothic",sans-serif';ctx.fillText(k.toUpperCase(),190+i*350,420);ctx.font='18px "Malgun Gothic",sans-serif';ctx.fillText('물 '+(state.seed[k].water?'있음':'없음')+' · '+(state.seed[k].warm?'따뜻함':'차가움'),190+i*350,454);});}
 const url=canvas.toDataURL('image/png');recordThumbnails.set(key,url);document.querySelectorAll('img[data-record-thumb]').forEach(img=>{if(img.dataset.recordThumb===r.id)img.src=url;});return url;})();pendingThumbnails.set(key,task);try{return await task;}finally{pendingThumbnails.delete(key);}}
function book(p){const bank=recordBank(state),selected=state.book.cards.map(id=>bank.find(r=>r.id===id)).filter(Boolean);return `<div class="activity-intro"><h2>${p?'사진에 내 설명을 더해 줘':'내 관찰 기록으로 책을 만들자'}</h2><p>${p?'제목 · 사진 설명 두 개 이상 · 한살이 비교 생각을 적어 줘.':'동물과 식물 사진을 함께 골라 세 장부터 여섯 장까지 담아.'}</p></div>${!p?`<div class="book-layout"><div class="record-shelf">${bank.map(r=>`<button class="record-card ${state.book.cards.includes(r.id)?'used':''}" data-carry="record:${r.id}" aria-label="${esc(r.title)} 사진 집기"><img data-record-thumb="${esc(r.id)}" src="${recordImage(r)}" alt="" draggable="false"><strong>${esc(r.title)}</strong><span>${r.kind==='animal'?'동물 관찰':'식물 관찰'}</span></button>`).join('')}</div><div class="book-drop" data-drop="book"><span class="book-label">MY LIFE STORY · ${selected.length}/6</span><button class="book-add" data-drop="book">선택한 사진 담기</button>${selected.length?selected.map((r,i)=>`<div class="book-mini"><span>${i+1}</span><img data-record-thumb="${esc(r.id)}" src="${recordImage(r)}" alt=""><strong>${esc(r.title)}</strong>${btn('앞으로','book-up',r.id,'',i===0)}${btn('뒤로','book-down',r.id,'',i===selected.length-1)}${btn('빼기','book-remove',r.id)}</div>`).join(''):'<div class="empty-book">사진을 이곳에 놓아 줘<br><small>내가 관찰한 순서, 설명하기 좋은 순서를 생각해 봐.</small></div>'}</div></div>`:`<div class="book-writing"><label class="field"><span>나의 이야기 제목</span><input data-field="book.title" maxlength="50" value="${esc(state.book.title)}" placeholder="어떤 이야기를 들려줄까?"></label><div class="caption-list">${selected.map((r,i)=>`<div class="caption-card"><img data-record-thumb="${esc(r.id)}" src="${recordImage(r)}" alt="${esc(r.title)}">${field(`${i+1}. ${esc(r.title)}`,'caption:'+r.id,state.book.captions[r.id]||'','사진에서 발견한 점을 내 말로 적어 줘.')}</div>`).join('')}</div>${field('한살이를 비교하고 발견한 생각','book.summary',state.book.summary,'생물마다 어떻게 자라고, 다음 세대가 시작하는지 비교해 봐.',3)}<div class="book-actions">${btn('화면으로 발표하기','present','','',!ready(state,8))}${btn('이야기 그림 저장','export','','primary',!ready(state,8))}</div></div>`}`;}
function clock(p){if(!p)return `<div class="clock-scene"><div class="clock-object">${art('clock','복원할 생명 시계')}<div class="clock-core ${state.clock.rings.length===5?'lit':''}">${art('core')}</div>${[0,1,2,3,4].map((n)=>`<button class="clock-socket ${state.clock.rings.includes(n)?'filled':''}" style="--angle:${n*72-90}deg" data-drop="ring:${n}" aria-label="${n+1}번 ${CHAPTER_NAMES[n]} 고리 자리">${state.clock.rings.includes(n)?art('ring'):'<span>'+(n+1)+'</span>'}</button>`).join('')}</div><div class="ring-shelf"><h2>내 기록으로 채우는 다섯 고리</h2><p>고리를 놓고, 빛나는 고리를 눌러 기록을 다시 봐.</p>${[0,1,2,3,4].filter(n=>!state.clock.rings.includes(n)).map(n=>`<button class="ring-item" data-carry="ring:${n}">${art('ring')}<span>${n+1}. ${CHAPTER_NAMES[n]}</span></button>`).join('')||'<p>모든 기록이 빛으로 연결됐어!</p>'}${state.clock.rings.length?`<div class="clock-proof"><strong>${CHAPTER_NAMES[state.clock.rings.at(-1)]}에서 가져온 내 기록</strong><p>${proofFor(state.clock.rings.at(-1))}</p></div>`:''}</div></div>`;
return `<div class="ending"><div class="ending-characters">${art('cheer')}${art('ipsaeCheer')}</div><div><p class="eyebrow">이제 교실 밖에서도 생명 탐험가!</p><h2>다음 관찰은 진짜 생명과 함께</h2><p>이곳에서는 모의 관찰을 했어. 주변 생물을 직접 기르거나 같은 장소에서 여러 날 관찰해 봐.</p>${field('내가 직접 관찰할 생물과 방법','clock.transfer',state.clock.transfer,'예: 화단의 봉선화를 매주 같은 곳에서 보고 그림으로 남길래.',3)}<div class="transfer-tip">날짜 · 생물의 모습 · 달라진 점을 글과 그림으로 기록해.</div>${btn('내 이야기 책 다시 펼치기','present')}</div></div>`;}
const activities=[observation,cycle,seedLab,journey,greenhouse,recovery,archives,garden,book,clock];

function mountMission(){if(state.mission===0&&!state.phase[0])selectedTool=selectedTool||'magnifier';}
function setField(path,value){if(path.startsWith('caption:'))state.book.captions[path.slice(8)]=value;else{const [section,key]=path.split('.');state[section][key]=value;}save();updateFooter();app.querySelectorAll('[data-action="export"],[data-action="present"]').forEach(n=>{if(state.mission===8)n.disabled=!ready(state,8);});}
document.addEventListener('input',e=>{if(e.target.dataset.field)setField(e.target.dataset.field,e.target.value);if(e.target.dataset.iqPlan){state.inquiry.plan[e.target.dataset.iqPlan]=e.target.value;save();updateFooter();}const range=e.target.dataset.range;if(!range)return;if(iq.range(range,e.target.value))return;
 if(range==='compare'){state.cycle.compared=true;app.querySelector('.wipe-after').style.clipPath=`inset(0 0 0 ${e.target.value}%)`;app.querySelector('.wipe-handle').style.left=e.target.value+'%';save();updateFooter();}
 if(range==='day'){state.journey.day=+e.target.value;save();const slot=app.querySelector('.growing');slot.outerHTML=growingPots();app.querySelector('#day-label').textContent=state.journey.day+'일째';}
 if(range.startsWith('archive-')){const kind=range.slice(8);if(kind==='animal')animalStep=+e.target.value;else plantStep=+e.target.value;}
});
document.addEventListener('change',e=>{if(e.target.dataset.range&&iq.range(e.target.dataset.range,e.target.value,true))return;if(e.target.dataset.range?.startsWith('archive-')){const range=e.target.dataset.range,value=e.target.value;render();const slider=app.querySelector(`[data-range="${range}"]`);slider?.focus();if(slider)slider.value=value;}});

function toggle(list,item){return list.includes(item)?list.filter(x=>x!==item):[...list,item];}
function useTool(payload,target){if(!payload||!target)return;const [kind,id]=target.split(':');
 if(kind==='inspect'){if(payload!=='magnifier')return toast('돋보기로 자세히 살펴보자.');const b=BIO.find(x=>x.id===id);dialog(`<div class="discovery-dialog">${art(id)}<div><p class="eyebrow">작은 생명 발견!</p><h2>${b.name}</h2><p>${b.detail}</p><strong>${b.feature}</strong>${btn('관찰 사진 남기기','capture-bio',id,'primary')}</div></div>`);return;}
 if(kind==='cycle'&&payload.startsWith('cycle:')){const a=+payload.split(':')[1],b=+id;[state.cycle.order[a],state.cycle.order[b]]=[state.cycle.order[b],state.cycle.order[a]];toast(phaseReady()?'시간 순서가 이어졌어!':'사진 자리를 바꿨어. 앞뒤 모습을 비교해 봐.');}
 else if(kind==='generation'&&payload==='new-egg'){state.cycle.generation=true;toast('맞아. 어른벌레가 낳은 알에서 다음 세대가 시작돼.');}
 else if(kind==='prepare'){if(state.completed.includes(2))return toast('진행한 실험의 준비 기록은 보관 중이야.');if(payload==='soil')state.seed.prepared[id].soil=true;else if(payload==='seeds'&&state.seed.prepared[id].soil)state.seed.prepared[id].seeds=true;else return toast('흙을 먼저 넣고 씨앗을 심어 줘.');toast(id.toUpperCase()+' 화분에 같은 양을 넣었어.');}
 else if(kind==='sensor'){if(payload!=='sensor-'+id.split('-')[1])return toast('물 센서와 빛 센서의 자리를 살펴봐.');if(!state.greenhouse.sensors.includes(id))state.greenhouse.sensors.push(id);toast(id.endsWith('water')?'흙에 물이 있어. 촉촉해!':'밝은 곳에 놓여 있어!');}
 else if(kind==='repair'){if(id!==weakSide())return toast('도움이 필요한 쪽의 잎과 줄기를 다시 살펴봐.');if(payload!=='repair-'+state.greenhouse.question)return toast('찾아낸 부족한 조건에 맞는 도구를 골라 줘.');state.recovery.repaired=true;toast('필요한 조건을 돌려줬어. 시간이 지나며 식물이 회복됐어!');}
 else if(kind==='garden'&&payload.startsWith('species:')){const species=payload.slice(8);if(classification[species]!==id)return toast(species==='rose'?'장미는 같은 식물이 여러 해를 살아.':speciesNames[species]+'의 시작과 한 해 뒤 모습을 다시 떠올려 봐.');state.garden.placements[species]=id;toast(speciesNames[species]+'의 정원을 찾았어! '+groupNames[id]+'.');}
 else if(kind==='book'&&payload.startsWith('record:')){const id=payload.slice(7);if(state.book.cards.includes(id))return toast('이미 책에 담은 사진이야.');if(state.book.cards.length===6)return toast('최대 여섯 장까지 담을 수 있어. 사진을 빼고 바꿔 봐.');if(recordBank(state).some(x=>x.id===id)){state.book.cards.push(id);if(!state.book.captions[id]){const note=id.startsWith('obs-')||id==='drawing'?state.discovery.note:id==='cycle'?state.cycle.note:id==='greenhouse'?state.recovery.note:'';if(note)state.book.captions[id]=note;}}}
 else if(kind==='ring'&&payload==='ring:'+id){const n=+id;if((n<4&&!state.completed.includes(n*2+1))||(n===4&&!ready(state,8)))return toast('이 고리에 담을 탐구 기록을 먼저 완성해 줘.');if(!state.clock.rings.includes(n))state.clock.rings.push(n);toast(['관찰한 나비의 변화가 첫 고리를 밝혔어.','직접 설계한 씨앗 실험이 두 번째 고리를 밝혔어.','식물을 도운 근거가 세 번째 고리를 밝혔어.','다양한 한살이 비교가 네 번째 고리를 밝혔어.','내 이야기 책이 마지막 고리를 밝혔어!'][n]);}
 else return toast('이 도구를 어디에 쓰면 좋을지 안내를 살펴봐.');selectedTool='';save();render();}

let drag=null,suppressClick=false;
document.addEventListener('pointerdown',e=>{const source=e.target.closest('[data-carry]');if(!source||e.button!==0)return;drag={source,payload:source.dataset.carry,x:e.clientX,y:e.clientY,ghost:null,pointer:e.pointerId};});
document.addEventListener('pointermove',e=>{if(!drag||drag.pointer!==e.pointerId)return;if(!drag.ghost&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>10){drag.ghost=drag.source.cloneNode(true);drag.ghost.className='drag-ghost';drag.ghost.removeAttribute('id');drag.ghost.setAttribute('aria-hidden','true');document.body.append(drag.ghost);}if(drag.ghost){e.preventDefault();drag.ghost.style.transform=`translate(${e.clientX-48}px,${e.clientY-48}px)`;document.querySelectorAll('.drop-hover').forEach(n=>n.classList.remove('drop-hover'));document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop]')?.classList.add('drop-hover');}},{passive:false});
document.addEventListener('pointerup',e=>{if(!drag)return;const current=drag;drag=null;if(current.ghost){const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop]');current.ghost.remove();suppressClick=true;setTimeout(()=>suppressClick=false,0);document.querySelectorAll('.drop-hover').forEach(n=>n.classList.remove('drop-hover'));if(target)useTool(current.payload,target.dataset.drop);}});
document.addEventListener('pointercancel',()=>{drag?.ghost?.remove();drag=null;document.querySelectorAll('.drop-hover').forEach(n=>n.classList.remove('drop-hover'));});
document.addEventListener('click',async e=>{if(suppressClick)return;const target=e.target.closest('button,[data-drop]');if(!target||target.disabled)return;
 if(target.dataset.drop&&selectedTool){useTool(selectedTool,target.dataset.drop);return;}
 if(target.dataset.drop?.startsWith('ring:')&&state.clock.rings.includes(Number(target.dataset.drop.split(':')[1]))){const n=Number(target.dataset.drop.split(':')[1]);if(n===4){await present();return;}const types=[['compare','observation'],['retry','seed'],['care'],['season']][n];const record=recordBank(state).filter(r=>types.includes(r.evidence?.type)).at(-1);if(record)iq.action('iq-replay',record.id);else dialog(`<div class="help-dialog"><h2>${CHAPTER_NAMES[n]}의 기록</h2><p>${proofFor(n)}</p>${btn('닫기','close')}</div>`);return;}
 if(target.dataset.carry){selectedTool=target.dataset.carry;document.querySelectorAll('[data-carry]').forEach(n=>{const yes=n===target;n.classList.toggle('selected',yes);n.setAttribute('aria-pressed',String(yes));});toast('선택했어. 놓을 곳을 누르거나 Enter로 선택해 줘.');return;}
 if(target.dataset.drop?.startsWith('inspect:'))return useTool('magnifier',target.dataset.drop);
 const {action,value}=target.dataset;if(!action)return;const handled=iq.action(action,value);if(handled){if(handled==='present'){if(modal.open)modal.close();await present();}if(handled==='records'){if(modal.open)modal.close();showRecords();}return;}
 if(action==='start'){state.intro=false;modal.close();save();return;}
 if(action==='close'){modal.close();return;}
 if(action==='open-mission'){modal.close();openMission(Number(value));return;}
 if(action==='intro-replay'){modal.close();showIntro();return;}
 if(action==='teacher-help'){modal.close();showTeacher();return;}
 if(action==='credits'){modal.close();showCredits();return;}
 if(action==='reset-ask'){modal.close();dialog(`<div class="help-dialog"><h2>새 탐험을 시작할까?</h2><p>이 브라우저에 저장된 새 탐험의 관찰·그림·이야기책이 지워져. 필요한 이야기 그림은 먼저 저장해 줘.</p>${btn('기록 유지하기','close','','primary')}${btn('기록 지우고 처음부터','reset-confirm')}</div>`);return;}
 if(action==='reset-confirm'){modal.close();state=fresh();save();render({focus:true});return;}
 if(action==='map'){state.screen='map';save();render({focus:true});return;}
 if(action==='phase-next'){if(!phaseReady())return;state.phase[state.mission]=1;selectedTool='';save();render({focus:true});return;}
 if(action==='phase-back'){state.phase[state.mission]=0;save();render({focus:true});return;}
 if(action==='finish'){finishMission();return;}
 if(action==='capture-bio'){if(!state.discovery.seen.includes(value))state.discovery.seen.push(value);modal.close();toast(BIO.find(x=>x.id===value).name+'의 관찰 사진을 남겼어.');}
 if(action==='clear-drawing')state.discovery.drawing=[];
 if(action==='question'){const[k,q]=value.split(':');if(state.completed.includes(k==='seed'?2:4))return;state[k].question=q;state[k].prediction=null;}
 if(action==='condition'){const[k,p,c]=value.split(':');if(state.completed.includes(k==='seed'?2:4))return;state[k][p][c]=!state[k][p][c];}
 if(action==='prediction'){const[k,v]=value.split(':');state[k].prediction=v;}
 if(action==='peek'){state.journey.peek=true;save();render();dialog(`<div class="root-inspection"><p class="eyebrow">얻은 시간 돋보기 사용 중</p><h2>${state.journey.day}일째 · 흙 속에서는?</h2><p>흙을 잘라 본 것처럼 나타낸 단면 모형이야. 씨앗 아래로 뿌리가 나왔는지 비교해 봐.</p><div class="root-pair">${['a','b'].map(k=>`<figure>${art('pot'+seedLevel(k,state.journey.day))}<figcaption>${k.toUpperCase()} 화분 · ${seedLevel(k,state.journey.day)?'뿌리가 보여':'뿌리가 아직 보이지 않아'}</figcaption></figure>`).join('')}</div>${btn('관찰하고 돌아가기','close','','primary')}</div>`);return;}
 if(action==='snapshot'){const day=state.journey.day;if(!state.journey.shots.some(x=>x.day===day))state.journey.shots.push({day});toast(day+'일째 두 화분의 사진을 남겼어.');}
 if(action==='winner')state.journey.winner=value;
 if(action==='reason')state.journey.reason=value;
 if(action==='compare-zoom')comparisonZoom=!comparisonZoom;
 if(action==='trait')state.recovery.traits=toggle(state.recovery.traits,value);
 if(action==='cause')state.recovery.cause=value;
 if(action==='archive-species'){const[type,id]=value.split(':');if(type==='animal'){activeAnimal=id;animalStep=0;}else{activePlant=id;plantStep=0;}}
 if(action==='archive-capture'){const type=value,id=type==='animal'?activeAnimal:activePlant,step=type==='animal'?animalStep:plantStep,list=state.archives[type==='animal'?'animalSeen':'plantSeen'];if(!list.includes(id+'-'+step))list.push(id+'-'+step);toast('이 모습을 탐구 기록에 담았어.');}
 if(action==='birth')state.archives.birth=value;
 if(action==='perennial')state.archives.perennial=value;
 if(action==='book-down'){const i=state.book.cards.indexOf(value);if(i>=0&&i<state.book.cards.length-1)[state.book.cards[i+1],state.book.cards[i]]=[state.book.cards[i],state.book.cards[i+1]];}
  if(action==='book-up'){const i=state.book.cards.indexOf(value);if(i>0)[state.book.cards[i],state.book.cards[i-1]]=[state.book.cards[i-1],state.book.cards[i]];}
 if(action==='book-remove')state.book.cards=state.book.cards.filter(x=>x!==value);
 if(action==='records'){showRecords();return;}
 if(action==='help'){showHelp();return;}
 if(action==='teacher'){showTeacher();return;}
 if(action==='motion'){state.settings.reducedMotion=!state.settings.reducedMotion;save();modal.close();render();return;}
 if(action==='present'){try{await present();}catch{toast('관찰 사진을 다시 불러온 뒤 책을 펼쳐 줘.');}return;}
 if(action==='export'){await downloadBook(target);return;}
 if(action==='reward-continue'){modal.close();state.screen='map';save();render({focus:true});return;}
 if(action==='next-mission'){modal.close();state.mission++;state.screen='mission';save();render({focus:true});return;}
 save();render();
});
function finishMission(){const n=state.mission;if(!ready(state,n))return toast('아직 남은 관찰과 기록을 확인해 줘.');if(state.completed.includes(n)){state.screen='map';save();render({focus:true});return;}if(!complete(state,n))return toast('남은 관찰을 먼저 확인해 줘.');save();const chapter=Math.floor(n/2);if(n%2===1){const r=REWARDS[chapter];dialog(`<div class="reward-dialog">${art('cheer','','reward-person')}<div><p class="eyebrow">${CHAPTER_NAMES[chapter]}의 빛을 되찾았어!</p><h2>${r.name}${n===9?'가 되었어!':'를 얻었어!'}</h2>${art(r.art,r.name,'reward-art')}<p>${r.use}</p><div class="earned-proof">${proofFor(chapter)}</div>${btn('밝아진 숲으로 돌아가기','reward-continue','','primary')}</div></div>`);}else{dialog(`<div class="small-completion">${art('ipsaeCheer')}<div><p class="eyebrow">탐험 기록 완료</p><h2>${MISSIONS[n].title}</h2><p>${MISSIONS[n].gain}</p>${btn('이 기록으로 다음 탐험','next-mission','','primary')}</div></div>`);}updateFooter();}
function proofFor(chapter){return [state.discovery.note,state.seed.question==='water'?'물의 차이를 둔 씨앗 실험으로 싹이 트는 조건을 확인했어.':'온도 차이를 둔 씨앗 실험으로 싹이 트는 조건을 확인했어.',state.recovery.note,'알과 새끼, 한해살이와 여러해살이를 비교했어.',state.book.title].map(esc)[chapter];}
async function prepareStoryImages(){await Promise.all(recordBank(state).filter(r=>state.book.cards.includes(r.id)&&(r.evidence||r.id==='drawing'||r.id.startsWith('seed-'))).map(prepareThumbnail));}
function storyData(){const bank=recordBank(state);return {title:state.book.title,summary:state.book.summary,cards:state.book.cards.map(id=>bank.find(r=>r.id===id)).filter(Boolean).map(r=>({...r,caption:state.book.captions[r.id]||'',image:recordImage(r)}))};}
async function present(){if(!ready(state,8))return toast('이야기 책의 제목, 사진 설명, 비교 생각을 먼저 완성해 줘.');await prepareStoryImages();const data=storyData();dialog(`<div class="presentation"><p class="eyebrow">나의 생명 탐구 이야기 · 모의 관찰</p><h2>${esc(data.title)}</h2><div class="presentation-cards">${data.cards.map(r=>`<figure><img src="${r.image}" alt="${esc(r.title)}"><figcaption><strong>${esc(r.title)}</strong><p>${esc(r.caption||r.detail)}</p>${iq.controls(r)}</figcaption></figure>`).join('')}</div><div class="story-summary">${esc(data.summary)}</div>${btn('이야기 그림 저장','export','','primary')}${btn('닫기','close')}</div>`);}
async function downloadBook(button){if(!ready(state,8))return;button.disabled=true;const label=button.textContent;button.textContent='그림으로 담는 중…';try{await prepareStoryImages();const blob=await exportStorybook(storyData());const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='나의-생명-탐구-이야기.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('이야기 그림을 저장했어. 친구에게 설명하며 보여 줘.');}catch(error){console.error('Story export failed',error);toast('그림을 저장하지 못했어. 이미지를 불러온 뒤 다시 눌러 줘.');}finally{if(button.isConnected){button.disabled=false;button.textContent=label;}}}
function showRecords(){const bank=recordBank(state);dialog(`<div class="records-dialog"><p class="eyebrow">나의 탐구 가방</p><h2>직접 모은 기록 ${bank.length}개</h2><div class="record-gallery">${bank.map(r=>`<figure><img data-record-thumb="${esc(r.id)}" src="${recordImage(r)}" alt=""><figcaption><strong>${esc(r.title)}</strong><p>${esc(r.detail)}</p>${iq.controls(r)}${r.evidence&&!state.book.cards.includes(r.id)?btn("기록 지우기","iq-delete",r.id):""}</figcaption></figure>`).join('')||'<p>나비의 숲에서 첫 관찰 사진을 모아 봐.</p>'}</div>${btn('닫기','close')}</div>`);}
function showHelp(){dialog(`<div class="help-dialog"><h2>지훈 & 잎새와 탐험하는 법</h2><p>지도에서 장소를 선택하면 길을 따라 걸어가. 입구에 도착하면 탐험을 시작할 수 있어.</p><p>확대 그림은 누르거나 방향키로 위치를 정해. 시간 손잡이는 끌거나 양옆 화살표를 눌러 움직여.</p><p>활동 도구와 사진은 <strong>끌어서 놓기</strong> 또는 <strong>도구 선택 → 대상 선택</strong>으로 쓸 수 있어. 키보드는 Tab과 Enter를 사용해.</p><p>지도 빈 영역에 초점을 두면 방향키로 길을 따라 이동해. 그림은 스페이스와 방향키로도 그릴 수 있어.</p><p>진행 기록은 이 기기의 브라우저에 저장돼. 다른 기기와 자동으로 연결되지는 않아. 브라우저 데이터를 지우면 기록도 사라져.</p><div class="help-actions">${btn('움직임 줄이기: '+(state.settings.reducedMotion?'켜짐':'꺼짐'),'motion')}${btn('선생님 안내','teacher-help')}${btn('시작 이야기 다시 보기','intro-replay')}${state.completed.includes(9)?btn('완성한 탐험 다시 보기','open-mission',9):''}${btn('정보와 출처','credits')}${btn('새 탐험 시작','reset-ask')}</div>${btn('닫기','close','','primary')}</div>`);}
function showCredits(){dialog(`<div class="help-dialog"><h2>정보와 출처</h2><p><strong>생명 시계 연구실 · 탐험 버전 0.3</strong><br>기획·제작: 생명 시계 연구실 프로젝트<br>구현·이미지 제작 보조: OpenAI Codex 및 생성형 AI</p><p>일러스트에는 사용자 제공 원화와 생성형 AI로 만든 이미지가 포함돼. 생물의 특징과 성장 장면은 학습을 돕는 대표적인 모형이야.</p><p>교육 내용 출처: 교육부(moe.go.kr), 2022 개정 과학과 교육과정 · 경기도교육청(goe.go.kr) 공개본. 식물의 빛 반응 참고: 미네소타대학교 익스텐션(extension.umn.edu).</p><p>ⓒ 2026 각 원저작권자. 무단 복제·재배포·상업적 이용 금지. 원본 이미지의 이용 허락은 배포 주체가 확인해 줘.</p>${btn('닫기','close','','primary')}</div>`);}
function showTeacher(){dialog(`<div class="help-dialog"><p class="eyebrow">교사 안내</p><h2>생물의 한살이를 탐구하는 열 가지 활동</h2><p><strong>[4과04-01]</strong> 동물의 한살이를 직접 관찰하고 글과 그림으로 표현하기<br><strong>[4과04-02]</strong> 식물이 자라는 조건을 찾는 실험 설계와 수행<br><strong>[4과04-03]</strong> 다양한 한살이를 비교하는 자료를 만들어 공유하기</p><p>앱의 관찰은 <strong>모의 탐구</strong>야. 실제 동물 기르기와 여러 날 직접 관찰을 함께 진행해 줘. 시간과 생장 그림은 대표적인 경향을 설명하며 실제 측정값이 아니야.</p><p>씨앗의 발아에서는 물·알맞은 온도를, 자라는 식물에서는 물·햇빛을 비교해. 빛이 부족한 식물은 가늘고 길게 자랄 수 있어 키만으로 건강을 판단하지 않아.</p><p>이 앱의 모의 관찰만으로 직접 관찰 성취기준을 완료한 것으로 평가하지 않아. 실제 곤충을 기르며 여러 날 관찰하고 글과 그림으로 남기는 수업을 함께 진행해 줘. 소개 자료는 친구 앞에서 발표하거나 PNG로 저장해 공유할 수 있어. 글자 수는 작성 여부만 확인하며 설명의 정확성은 교사가 살펴봐.</p><p><a href="https://www.goe.go.kr/resource/old/BBSMSTR_000000030136/BBS_202411110127574203.pdf" target="_blank" rel="noopener">교육청 성취기준 원문 · 81~83쪽</a></p><p>기존 버전의 저장 기록은 그대로 보존돼. 새 탐험은 별도의 기록으로 저장해.</p><p class="credits">일러스트: 사용자 제공 원화 및 AI 생성 보조 이미지. 교육과정 근거: 교육부 고시 제2022-33호 별책9 과학과 교육과정. 외부 전송·회원 가입 없음.</p>${btn('닫기','close','','primary')}</div>`);}

function bindDrawing(){const canvas=app.querySelector('#observation-drawing');if(!canvas)return;const ctx=canvas.getContext('2d');ctx.lineCap='round';ctx.lineJoin='round';ctx.lineWidth=4;ctx.strokeStyle='#315d45';let stroke=null,pen=[.5,.5],keyDown=false;
 const draw=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);state.discovery.drawing.forEach(line=>{ctx.beginPath();line.forEach(([x,y],i)=>i?ctx.lineTo(x*canvas.width,y*canvas.height):ctx.moveTo(x*canvas.width,y*canvas.height));ctx.stroke();});};draw();
 const point=e=>{const r=canvas.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))];};
 canvas.addEventListener('pointerdown',e=>{e.preventDefault();canvas.focus();canvas.setPointerCapture(e.pointerId);stroke=[point(e)];state.discovery.drawing.push(stroke);});canvas.addEventListener('pointermove',e=>{if(!stroke)return;stroke.push(point(e));draw();});canvas.addEventListener('pointerup',()=>{stroke=null;save();updateFooter();});canvas.addEventListener('pointercancel',()=>{stroke=null;save();});
 canvas.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();keyDown=!keyDown;if(keyDown){stroke=[[...pen]];state.discovery.drawing.push(stroke);}else{stroke=null;save();updateFooter();}return;}const dirs={ArrowLeft:[-.025,0],ArrowRight:[.025,0],ArrowUp:[0,-.025],ArrowDown:[0,.025]};if(!dirs[e.key])return;e.preventDefault();pen=pen.map((v,i)=>Math.min(.98,Math.max(.02,v+dirs[e.key][i])));if(keyDown&&stroke){stroke.push([...pen]);draw();}});canvas.addEventListener('blur',()=>{stroke=null;keyDown=false;save();updateFooter();});
}
save();render();

function updateViewport(){document.documentElement.style.setProperty('--app-height',(window.visualViewport?.height||innerHeight)+'px');}
updateViewport();window.addEventListener('resize',updateViewport);window.visualViewport?.addEventListener('resize',updateViewport);
